-- Chunk 5/5
BEGIN;

UPDATE tools SET long_description = E'Looker Studio, c''est outil de reporting et dashboards Google. Connexion native à GA4, Sheets, BigQuery. L''outil est entièrement gratuit. Particulièrement pertinent pour les data-analyst et les community-manager.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : reporting Google Ads/Analytics, dashboards clients. À éviter si : données non-Google — Metabase plus flexible. Gratuit — toujours pertinent si vous utilisez Google Analytics.', long_description_en = E'Looker Studio is google reporting and dashboard tool. Native connection to GA4, Sheets, BigQuery. It''s completely free. Most relevant for data-analyst and community-manager.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'looker-studio';
UPDATE tools SET long_description = E'Retool, c''est construire des outils internes rapidement : dashboards, admin panels, CRUD. À partir de 8.66€/mois. Particulièrement pertinent pour les developpeur-solo et les cto-lead-tech.\n\nGain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : outils internes : backoffice, admin panel, workflows. À éviter si : application client-facing — Bubble ou Webflow plus adaptés. Rentable dès 2 outils internes en production.', long_description_en = E'Retool is build internal tools fast: dashboards, admin panels, CRUD. Starting at €8.66/month. Most relevant for solo developers and cto-lead-tech.\n\nEstimated time saving: 8h/month with regular use.' WHERE slug = 'retool';
UPDATE tools SET long_description = E'Confluence, c''est wiki d''entreprise Atlassian. Documentation technique et knowledge base. À partir de 4.98€/mois. Particulièrement pertinent pour les cto-lead-tech et les manager-dsi.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : jira déjà en place — intégration native précieuse. À éviter si : sans Jira — Notion est meilleur sur tous les points. Pertinent uniquement si vous avez déjà l''écosystème Atlassian. Si le budget le permet, notion est souvent une meilleure option.', long_description_en = E'Confluence is atlassian enterprise wiki. Technical documentation and knowledge base. Starting at €4.98/month. Most relevant for cto-lead-tech and manager-dsi.\n\nEstimated time saving: 3h/month with regular use.\n\nIf budget allows, notion is often a better fit.' WHERE slug = 'confluence';
UPDATE tools SET long_description = E'Canny, c''est collecte et vote de feedback utilisateurs. Roadmap publique ou privée. À partir de 85.74€/mois. Particulièrement pertinent pour les fondateurs SaaS et les product-manager.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : collecte de feedback publique avec vote communauté. À éviter si : productboard déjà en place — doublon feedback. Free tier généreux pour les early-stage SaaS.', long_description_en = E'Canny is user feedback collection and voting. Public or private roadmap. Starting at €85.74/month. Most relevant for SaaS founders and product-manager.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'canny';
UPDATE tools SET long_description = E'Overlord, c''est transfert vectoriel direct Illustrator → After Effects en un clic. Gain de temps massif. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les motion-video et les graphiste-da.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : workflow Illustrator + After Effects quotidien. À éviter si : pas de travail vectoriel dans AE. Achat unique — rentable dès la première journée de motion design.', long_description_en = E'Overlord is direct vector transfer Illustrator → After Effects in one click. Massive time saving. Core features are free, with paid plans for advanced use. Most relevant for motion-video and graphiste-da.\n\nEstimated time saving: 5h/month with regular use.' WHERE slug = 'ae-overlord';
UPDATE tools SET long_description = E'Newton 3, c''est simulateur de physique 2D pour After Effects. Collisions, gravité, ressorts réalistes. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les motion-video.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : animations avec physique réaliste, typographie animée. À éviter si : animations simples — pas besoin de physique. Achat unique — amortissable dès un projet avec typographie physique.', long_description_en = E'Newton 3 is 2D physics simulator for After Effects. Realistic collisions, gravity, springs. Core features are free, with paid plans for advanced use. Most relevant for motion-video.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'ae-newton3';
UPDATE tools SET long_description = E'Duik Ángela, c''est le plugin de rigging de personnages de référence pour After Effects. Gratuit. L''outil est entièrement gratuit. Particulièrement pertinent pour les motion-video et les illustrateur.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : animation de personnages, marionnettes 2D. À éviter si : pas d''animation de personnages dans vos projets. Gratuit — toujours pertinent pour l''animation de personnages.', long_description_en = E'Duik Ángela is the reference character rigging plugin for After Effects. Free. It''s completely free. Most relevant for motion-video and illustrateur.\n\nEstimated time saving: 6h/month with regular use.' WHERE slug = 'ae-duik';
UPDATE tools SET long_description = E'Bodymovin / Lottie, c''est export d''animations After Effects en JSON Lottie pour le web et mobile. L''outil est entièrement gratuit. Particulièrement pertinent pour les motion-video et les developpeur-solo.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : animations web/mobile légères depuis After Effects. À éviter si : rive.app si vous voulez un workflow natif sans AE. Gratuit — toujours pertinent si vous livrez des animations web.', long_description_en = E'Bodymovin / Lottie is export After Effects animations to Lottie JSON for web and mobile. It''s completely free. Most relevant for motion-video and solo developers.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'ae-bodymovin';
UPDATE tools SET long_description = E'Red Giant Magic Bullet Suite, c''est suite d''étalonnage et look cinématique : Looks, Colorista, Denoiser. À partir de 8.66€/mois. Particulièrement pertinent pour les motion-video et les photographe.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : étalonnage cinématique professionnel, finitions haute gamme. À éviter si : daVinci Resolve couvre déjà l''étalonnage — doublon si utilisé. Rentable si vous livrez des vidéos avec look cinéma régulièrement.', long_description_en = E'Red Giant Magic Bullet Suite is colour grading and cinematic look suite: Looks, Colorista, Denoiser. Starting at €8.66/month. Most relevant for motion-video and photographe.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'ae-red-giant';
UPDATE tools SET long_description = E'Iconify for Figma, c''est accès à 150 000+ icônes de toutes les bibliothèques directement dans Figma. L''outil est entièrement gratuit. Particulièrement pertinent pour les ux-ui et les graphiste-da.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : tout designer Figma — incontournable. À éviter si : jamais. Gratuit — toujours pertinent.', long_description_en = E'Iconify for Figma is access 150,000+ icons from all libraries directly in Figma. It''s completely free. Most relevant for ux-ui and graphiste-da.\n\nEstimated time saving: 2h/month with regular use.' WHERE slug = 'figma-iconify';
UPDATE tools SET long_description = E'Anima, c''est export de designs Figma en code React/HTML/CSS. Handoff développeur automatisé. À partir de 26.85€/mois. Particulièrement pertinent pour les ux-ui et les developpeur-solo.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : handoff fréquent vers des devs React/HTML. À éviter si : figma Dev Mode déjà utilisé par votre équipe. Rentable dès 5 handoffs développeur par mois.', long_description_en = E'Anima is export Figma designs to React/HTML/CSS code. Automated developer handoff. Starting at €26.85/month. Most relevant for ux-ui and solo developers.\n\nEstimated time saving: 5h/month with regular use.' WHERE slug = 'figma-anima';
UPDATE tools SET long_description = E'Nik Collection, c''est suite de filtres photo professionnels : Analog Efex, Color Efex, Silver Efex. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les photographe.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : photographie artistique avec besoins de looks spécifiques. À éviter si : capture One ou Lightroom couvrent vos besoins basiques. Achat unique — rentable si vous retouchez en volume.', long_description_en = E'Nik Collection is professional photo filter suite: Analog Efex, Color Efex, Silver Efex. Core features are free, with paid plans for advanced use. Most relevant for photographe.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'nik-collection';
UPDATE tools SET long_description = E'Revit, c''est le logiciel BIM de référence pour architectes et ingénieurs structure. À partir de 268.47€/mois. Particulièrement pertinent pour les architecte-bim.\n\nGain de temps estimé : 10h/mois pour un usage régulier.\n\nÀ garder si : architecture, structure, MEP — outil de production central. À éviter si : jamais si vous faites du BIM. Incontournable en architecture professionnelle.', long_description_en = E'Revit is the reference BIM software for architects and structural engineers. Starting at €268.47/month. Most relevant for architecte-bim.\n\nEstimated time saving: 10h/month with regular use.' WHERE slug = 'revit';
UPDATE tools SET long_description = E'SketchUp Pro, c''est modélisation 3D intuitive pour architectes, décorateurs et scénographes. À partir de 29.44€/mois. Particulièrement pertinent pour les architecte-bim et les scenographe.\n\nGain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : architecture intérieure, scénographie, modélisation rapide. À éviter si : bIM — Revit est plus adapté aux projets complexes. Incontournable pour la scénographie et l''archi intérieure. Alternative gratuite à considérer : blender.', long_description_en = E'SketchUp Pro is intuitive 3D modelling for architects, interior designers, and set designers. Starting at €29.44/month. Most relevant for architecte-bim and scenographe.\n\nEstimated time saving: 8h/month with regular use.\n\nFree alternative worth considering: blender.' WHERE slug = 'sketchup-pro';
UPDATE tools SET long_description = E'Zeplin, c''est handoff design-développement avec specs automatiques et assets exportés. À partir de 6.93€/mois. Particulièrement pertinent pour les ux-ui et les developpeur-solo.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : équipe sans Figma ou besoin de specs en dehors de Figma. À éviter si : figma déjà en place — Dev Mode remplace entièrement Zeplin. Inutile si vous avez Figma — doublon évident. Si le budget le permet, figma est souvent une meilleure option.', long_description_en = E'Zeplin is design-development handoff with automatic specs and exported assets. Starting at €6.93/month. Most relevant for ux-ui and solo developers.\n\nEstimated time saving: 3h/month with regular use.\n\nIf budget allows, figma is often a better fit.' WHERE slug = 'zeplin';
UPDATE tools SET long_description = E'Rive, c''est animation interactive native pour le web et mobile. Remplace Lottie pour les projets complexes. À partir de 12.12€/mois. Particulièrement pertinent pour les ux-ui et les motion-video.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : animations interactives pour apps ou sites — state machines. À éviter si : animations simples — Bodymovin/Lottie depuis After Effects suffit. Gratuit pour les projets publics — toujours pertinent.', long_description_en = E'Rive is native interactive animation for web and mobile. Replaces Lottie for complex projects. Starting at €12.12/month. Most relevant for ux-ui and motion-video.\n\nEstimated time saving: 5h/month with regular use.' WHERE slug = 'rive';

COMMIT;
